'use strict';
(()=>{const C=RPG_RAID_LOOT,B=RPG_ACCOUNT_BRIDGE,$=s=>document.querySelector(s),fmt=n=>Math.ceil(n||0).toLocaleString('ko-KR'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dialog=document.createElement('dialog');dialog.id='fusion-dialog';dialog.className='fusion-dialog';dialog.innerHTML='<div class="fusion-shell"><header><div><small>RAID FUSION</small><h2>보스의 힘을, 내 장비에.</h2></div><button id="fusion-close" aria-label="융합 창 닫기">×</button></header><div class="fusion-scroll"><p id="fusion-message" role="status" aria-live="polite"></p><div id="fusion-body"></div></div></div>';document.body.append(dialog);let state=null,owner=null,hero=null,slot='weapon',busy=false,notice='',lastOwner=null,requestSerial=0;
function api(){return window.RPG_ACCOUNT_UI;}function uid(){return api()?.account?.user?.id||null;}function heroes(){return B.snapshot().heroes.map((h,id)=>({...h,id})).filter(h=>h.recruited);}function icon(s,cls=''){return `<span class="fusion-icon ${cls}" style="--fusion-cell:${C.slots.indexOf(s)}" aria-hidden="true"></span>`;}
function apply(data){if(!data||data.owner!==uid()||state?.owner===data.owner&&data.revision<state.revision)return false;state=C.clean(data);owner=data.owner;B.fusion.apply(state);return true;}
async function refresh(){const id=uid(),serial=++requestSerial;if(!id){state=null;owner=null;return;}const {data,error}=await api().client.rpc('rpg_fusion_command',{p_cmd:'view'});if(uid()!==id||serial!==requestSerial)return;if(error)throw error;apply(data);}
function render(){const list=heroes();if(!list.some(h=>h.id===hero))hero=list[0]?.id??null;$('#fusion-message').textContent=notice;const host=$('#fusion-body');if(!uid()){host.innerHTML='<section class="fusion-empty"><h3>동료와 보스를 잡고, 더 강해지세요.</h3><p>레이드 융합은 구글 계정에 보관돼요.<br>게스트의 캐릭터와 장비도 연결해서 이어갈 수 있어요.</p><button data-fusion="login">구글 계정 연결</button></section>';return;}if(!state||owner!==uid()){host.innerHTML='<p class="fusion-empty">융합 보관함을 불러오는 중이에요.</p><button data-fusion="refresh">다시 확인</button>';return;}if(hero===null){host.innerHTML='<section class="fusion-empty"><h3>함께할 원정대원이 필요해요.</h3><p>캐릭터를 만든 뒤 클라우드에 저장해 주세요.</p></section>';return;}
const item=state.collection[slot],level=item.level,on=state.loadouts[hero][slot],max=level>=10,current=B.fusion.inspect(hero,state),action=!level?'craft':!on?'equip':max?null:'grow',projected=action?C.project(state,hero,slot,action):state;if(action==='craft')projected.loadouts[hero][slot]=true;const next=B.fusion.inspect(hero,projected),bonus=C.bonus(projected,hero),price=!level?90:item.copies>0?0:C.cost(level),ready=action&&(action==='equip'||item.copies>0||state.crystals>=price),label=!level?'제작하고 융합하기':!on?'이 슬롯에 융합하기':max?'최고 단계 달성':item.copies>0?'중복 융합체로 성장':'융합체 성장';
host.innerHTML=`<div class="fusion-toolbar"><label>융합할 캐릭터<select id="fusion-hero">${list.map(h=>`<option value="${h.id}" ${h.id===hero?'selected':''}>${esc(RPG_DATA.characters[h.id].name)} · ${esc(RPG_DATA.characters[h.id].classes[h.cell].name)}</option>`).join('')}</select></label><div class="fusion-wallet"><small>융합 조각</small><strong>✦ ${fmt(state.crystals)}</strong></div></div><nav class="fusion-slots" aria-label="융합 부위">${C.slots.map(s=>`<button data-fusion-slot="${s}" aria-pressed="${s===slot}">${icon(s)}<span>${C.labels[s]}</span><small>${state.collection[s].level?'Lv.'+state.collection[s].level:'미보유'}${state.loadouts[hero][s]?' · 융합 중':''}</small></button>`).join('')}</nav><div class="fusion-layout"><section class="fusion-showcase ${on?'is-fused':''}"><span class="fusion-boss">폐광의 거신 · ${C.labels[slot]}</span><div class="fusion-orbit">${icon(slot,'large')}<i></i></div><h3>${C.names[slot]}</h3><span class="fusion-grade">${level?'Lv.'+level+' / 10':'미보유'} · ${on?'슬롯에 융합 중':level?'보관 중':'제작 가능'}</span><p>${slot==='weapon'?'거신의 송곳니가 무기에 깃들어<br>모든 공격에 힘을 더합니다.':slot==='armor'?'거신의 심장을 갑옷에 새겨<br>체력과 방어력을 높입니다.':'수정의 눈이 전투를 지켜보며<br>공격력과 체력을 함께 높입니다.'}</p></section><section class="fusion-detail"><div class="fusion-power"><small>${action?'적용 후 전투력':'현재 전투력'}</small><div><span>${fmt(current.power)}</span><i>→</i><strong>${fmt(next.power)}</strong></div><b>${next.power>current.power?'▲ +'+fmt(next.power-current.power):on?'보스의 힘이 적용되고 있어요.':'융합하면 실제 전투력이 상승해요.'}</b></div><dl class="fusion-stats">${[['attack','공격력'],['maxHP','최대 체력'],['armor','방어력']].map(([k,l])=>`<div><dt>${l}</dt><dd>${fmt(current.stats[k])}<span>→</span><b>${fmt(next.stats[k])}</b></dd></div>`).join('')}</dl><div class="fusion-cost"><span>${action==='equip'?'보유한 융합체':max?'성장 완료':item.copies>0?'중복 융합체':'필요한 융합 조각'}</span><strong>${action==='equip'?'재료 소모 없음':max?'MAX':item.copies>0?'1개 / '+item.copies+'개 보유':fmt(price)+'개'}</strong></div><button class="fusion-submit" data-fusion="${action||'none'}" ${busy||!ready?'disabled':''}>${busy?'반영 중…':label}<span>✦</span></button>${on?'<button class="fusion-remove" data-fusion="unequip" '+(busy?'disabled':'')+'>융합 해제 · 재료 손실 없음</button>':''}<p class="fusion-rules">성공률 100% · 하락·파괴 없음<br>장비를 교체해도 유지돼요. 융합체 성장은 원정대가 공유하고, 장착은 캐릭터별로 선택해요.</p></section></div><details class="fusion-guide"><summary>레이드에서 어떻게 얻나요?</summary><p>하루 보상 3회 · 클리어마다 조각 30개 확정<br>추가로 20% 확률로 3부위 중 하나 획득 · 부위별 확률 동일<br>조각 90개로 원하는 부위 확정 제작 · 중복은 성장에 먼저 사용<br>기존 레이드 결정은 같은 수량의 융합 조각으로 이어집니다.</p><button data-fusion="raid">레이드 입장 →</button></details>`;$('#fusion-hero').onchange=e=>{hero=Number(e.target.value);notice='';render();};}
async function open(){notice='';const active=B.snapshot().active;if(active!==null&&heroes().some(h=>h.id===active))hero=active;B.pause(true);if(!dialog.open)dialog.showModal();render();try{await refresh();render();}catch(e){notice=e.code==='PGRST202'?'보상 보관함 연결을 준비 중이에요. 잠시 후 다시 확인해 주세요.':e.message||'연결을 확인해 주세요.';render();}}
function close(){dialog.close();B.pause(false);}$('#fusion-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',()=>B.pause(false));
dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-fusion],[data-fusion-slot]');if(!b||busy)return;if(b.dataset.fusionSlot){slot=b.dataset.fusionSlot;notice='';render();return;}const cmd=b.dataset.fusion;if(cmd==='login'){close();api()?.open();return;}if(cmd==='raid'){close();document.dispatchEvent(new Event('rpg:raid-open'));return;}if(cmd==='refresh'){open();return;}if(!['craft','grow','equip','unequip'].includes(cmd)||owner!==uid())return;const id=uid(),selectedHero=hero,selectedSlot=slot,before=B.fusion.inspect(hero,state).power;busy=true;notice='';render();try{const response=await api().client.rpc('rpg_fusion_command',{p_cmd:cmd,p_hero:selectedHero,p_slot:selectedSlot,p_revision:state.revision});if(response.error)throw response.error;if(uid()!==id)return;if(!apply(response.data))return;const after=B.fusion.inspect(selectedHero,state).power;notice=(cmd==='grow'?'융합체 성장 완료':cmd==='unequip'?'융합 해제 완료':'융합 완료')+(after>before?' · 전투력 +'+fmt(after-before):'');document.dispatchEvent(new Event('rpg:fusion-changed'));api()?.auto?.flush();}catch(err){notice=err.code==='PT409'?'다른 요청이 먼저 반영됐어요. 최신 보관함으로 갱신했어요.':err.message||'연결을 확인해 주세요.';try{await refresh();}catch{}}finally{busy=false;render();if(notice.startsWith('융합')&&!notice.startsWith('융합 해제')){dialog.classList.remove('fusion-success');void dialog.offsetWidth;dialog.classList.add('fusion-success');}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-raid-fusion-open]'))open();});document.addEventListener('rpg:fusion-open',open);document.addEventListener('rpg:account-render',()=>{const id=uid();if(lastOwner===id)return;lastOwner=id;state=null;owner=null;requestSerial++;if(id)refresh().catch(()=>{});else if(B.snapshot().raidFusion)B.fusion.apply(null);if(dialog.open)render();});document.addEventListener('rpg:progress-applied',()=>{if(uid())refresh().then(()=>{if(dialog.open)render();}).catch(()=>{});});document.addEventListener('rpg:raid-reward',e=>{if(apply(e.detail?.fusion)&&dialog.open)render();});window.RPG_RAID_FUSION_UI={open,refresh,accept:data=>{if(apply(data)&&dialog.open)render();}};
})();
